def from_base_url(apps, schema_editor):
    """Every connection that is not revoked or failed gets a STAGED
    destination (host and port from its base URL, its private CA bundle as
    the trust anchor) with NO approved address: nothing is sent to it until
    an administrator approves the addresses it resolves to (B2)."""
    from urllib.parse import urlsplit
    Connection = apps.get_model('connect', 'Connection')
    ApprovedDestination = apps.get_model('connect', 'ApprovedDestination')
    for c in Connection.objects.exclude(state__in=('revoked', 'failed')).exclude(base_url=''):
        u = urlsplit(c.base_url)
        if not u.hostname:
            continue
        ApprovedDestination.objects.get_or_create(connection=c, defaults={
            'host': u.hostname.lower().rstrip('.'), 'port': u.port or 443, 'addresses': [],
            'trust': 'private_ca' if c.tls_ca_bundle else 'system', 'ca_bundle': c.tls_ca_bundle or '',
            'expected_installation_id': c.remote_installation_id or '', 'status': 'staged'})


